cd /tmp/supp_check && python3 -c "
import ast, sys, os

errors = []
for root, dirs, files in os.walk('code'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            try:
                with open(path) as fh:
                    ast.parse(fh.read())
            except SyntaxError as e:
                errors.append(f'{path}: {e}')

if errors:
    for e in errors:
        print(f'SYNTAX ERROR: {e}')
else:
    print(f'All {sum(1 for r,d,fs in os.walk(\"code\") for f in fs if f.endswith(\".py\"))} Python files parse OK')
"
